_ex = ['Interviews: five freelancers rank quiet zone, fast internet and price first; coffee comes last. The layout follows the answers.', '20 seats at 3 square metres = 60 plus 25 for walkways and 20 for a meeting room = 105 square metres.', 'A sign lists the maximum of 24 people and the nearest exits; the fire adviser signs off the checklist.', 'Fixed costs 3,000; price 120: 25 members to break even; with 20 seats, meeting-room income lowers the number.', "Day pass 12; week 50; month 120. A member can leave with 30 days' notice.", 'Monday coffee and Friday demo: members report knowing five others after a month.', 'Speed tested daily: target 100 Mbit/s; two dips fixed with a router change.', '420 of 600 seat-days used = 70%; revenue per seat 98 for the month; satisfaction 4.3 out of 5.']
_extra = ['Visit two coworking spaces and note what members do.', 'Check sockets, light and air flow at busy times.', 'List quiet rules and test them with members.', 'Plan a first-aid kit and a trained person.', 'Check accessibility of doors, toilets and desks.', "Keep a visitors' log.", 'Write a welcome sheet with Wi-Fi and rules.', "Plan storage for members' belongings.", 'Add the space to a local map listing.', 'Keep a cleaning log by the door.', 'Offer a trial day for new members.', 'Ask for one idea from each member every month.', 'Review pricing every quarter.', 'Check insurance and licence renewals.', 'Prepare for outages with a backup link.', 'Write a 90-day plan with occupancy and satisfaction targets.']
C['deep']['mods'] = [(m[0], _ex[i], m[2]) for i, m in enumerate(C['deep']['mods'])]
C['deep']['extra'] = [_extra[2*i:2*i+2] for i in range(8)]
_np = [['Define who your members will be, such as freelancers and small teams, and survey ten of them about what they need before you choose a space.', 'Calculate how many members you need to cover rent and running costs, for example 24 desks at an average of 120 a month, and check that figure is realistic locally.'], ['Allow roughly 3 to 5 square metres per desk including walkways, include a quiet zone, a phone booth and a social area, and sketch the plan before buying any furniture.', 'Check power sockets, internet speed and lighting at every desk, and test the connection at the busiest time of day.'], ['Write simple house rules on noise, guests, cleaning and opening hours, and mark the fire exits and a first-aid kit where everyone can see them.', 'Ask a qualified adviser which insurance cover and local rules apply to your space, keep every document in one folder, and review them each year.'], ['List all monthly costs, including rent, utilities, internet, cleaning and supplies, and divide the total by the number of desks to find your minimum price per desk.', "Offer clear tiers such as day pass, hot desk and fixed desk, and compare the margin of each tier so that no plan loses money."], ['Use one booking tool where members reserve rooms in one-hour blocks, and set a fair limit, such as four free hours a week of meeting-room use.', 'Write a simple membership agreement stating the notice period, payment date and house rules, and give each new member a welcome pack and a short tour.'], ['Hold one regular event each month, such as a lunch talk, and ask members to suggest topics so the programme reflects what they want.', 'Introduce each new member to two existing members in their first week, and keep a notice board or group chat for requests and offers.'], ['Create a daily checklist covering opening, cleaning, supplies and locking up, and rotate who signs it off so no duty is missed.', 'Log every repair and complaint with its date, aim to fix urgent items within 24 hours, and tell the affected member what was done.'], ['Track occupancy, revenue per desk, member churn and satisfaction each month, and show the same four numbers in one simple chart.', 'Ask members for feedback twice a year, act on the most common suggestion, and report back on what you changed and what you could not.']]
C['mods'] = [(m[0], m[1], list(m[2])+_np[i], m[3], m[4], m[5]) for i, m in enumerate(C['mods'])]

_dupfix = {"2": "A room for 12 desks needs 36 square metres for the desks, 15 for walkways and 12 for a booth and storage: 63 in all.", "3": "A notice shows the 18-person limit, the fire door and the first-aid box; the monthly check of extinguishers is logged.", "4": "Fixed 2,000; day price 15: 134 day passes a month break even; adding 10 monthly members at 90 cuts that to 74.", "5": "A flexible desk is 80 a month, a fixed desk 130 and a private room 400; a plan can be paused once a year.", "6": "A Wednesday skills lunch draws 14 members; six say they found a client or partner through it in two months.", "7": "A cleaning log is signed twice a day; a missed Thursday check is fixed by a reminder on the manager's phone.", "8": "250 of 400 desk-days used = 62.5%; revenue per desk 71; satisfaction 4.5. Action: extend evening hours to lift use."}
C['deep']['mods'] = [(m[0], _dupfix.get(str(i + 1), m[1]), m[2]) for i, m in enumerate(C['deep']['mods'])]
C['intro_add'] = ["You will be able to define your target members and test whether enough of them exist to cover your space's costs.", 'You will be able to plan desks, quiet zones and social areas, and check power and connection quality before furnishing.', 'You will be able to set house rules, mark safety equipment and organise the insurance and local-rule paperwork a shared space needs.', 'You will be able to find your break-even price per desk and compare the margins of day, hot-desk and fixed-desk tiers.', 'You will be able to run fair room booking and write a membership agreement that makes joining and leaving simple.', 'You will be able to plan a monthly event and introductions that turn separate desk users into a connected community.', 'You will be able to run daily checklists and a repair log so the space stays clean, stocked and dependable.', 'You will be able to track four monthly numbers and act on member feedback to improve occupancy and retention.']
